old_property = '''def _extract_property(text: str) -> tuple[str, str | None, str, str, list[dict[str, Any]], list[str]]:\n    matches: list[tuple[PropertyRule, str, int]] = []\n    for rule in PROPERTY_RULES:\n        hit = _find_alias(text, rule.aliases)\n        if hit:\n            alias, position = hit\n            matches.append((rule, alias, position))\n    if not matches:\n        return "未知", None, "未知", "unknown", [], ["unknown_property_type"]\n    # A generic alias embedded in a longer explicit type (e.g. "别墅" inside\n    # "联排别墅") must not manufacture a contradiction.  Retain independent\n    # type mentions such as "排屋/别墅" as an ambiguity.\n    specific_hits = [item for item in matches if len(item[1]) > 2]\n    filtered = []\n    for candidate in matches:\n        rule, alias, position = candidate\n        if len(alias) <= 2 and any(alias in other_alias and rule.family != other_rule.family for other_rule, other_alias, _ in specific_hits):\n            continue\n        filtered.append(candidate)\n    matches = filtered\n    families = {rule.family for rule, _alias, _position in matches}\n    evidence = [_evidence(rule.display, "raw_property_alias", "high", alias) for rule, alias, _position in matches]\n    if len(families) > 1:\n        # Independent marketing alternatives such as "排屋/别墅" remain unsafe.\n        return "未知", None, "未知", "ambiguous", evidence, ["ambiguous_property_type"]\n    matches.sort(key=lambda item: (-len(item[1]), item[2]))\n    rule = matches[0][0]\n    return rule.family, rule.subtype or None, rule.display, "confirmed", evidence, []\n'''

new_property = '''_INVENTORY_MENU_MARKER = re.compile(\n    r"(?:户型选择|房型选择|可选户型|可选房型|户型可选|房型可选|库存户型|其他户型|更多户型|大量房源|房源充足)",\n    flags=re.I,\n)\n\n\ndef _strip_inventory_menu_segments(text: str) -> tuple[str, list[str]]:\n    current: list[str] = []\n    inventory: list[str] = []\n    for raw_line in str(text or "").splitlines() or [str(text or "")]:\n        line = clean_text(raw_line)\n        if not line:\n            continue\n        marker = _INVENTORY_MENU_MARKER.search(line)\n        if marker:\n            prefix = line[:marker.start()].strip(" ，,；;｜|")\n            if prefix:\n                current.append(prefix)\n            inventory.append(line[marker.start():])\n            continue\n        choice_list = bool(\n            re.search(r"(?:单间|studio|\\d{1,2}\\s*房)\\s*[／/|、,，]\\s*(?:单间|studio|\\d{1,2}\\s*房)", line, flags=re.I)\n            and re.search(r"(?:都有|均有|可选|任选|选择)", line, flags=re.I)\n        )\n        if choice_list:\n            inventory.append(line)\n            continue\n        current.append(line)\n    return "\\n".join(current), inventory\n\n\ndef _property_matches(text: str) -> list[tuple[PropertyRule, str, int]]:\n    matches: list[tuple[PropertyRule, str, int]] = []\n    for rule in PROPERTY_RULES:\n        hit = _find_alias(text, rule.aliases)\n        if hit:\n            alias, position = hit\n            matches.append((rule, alias, position))\n    return matches\n\n\ndef _resolve_property_matches(\n    matches: list[tuple[PropertyRule, str, int]],\n    *,\n    evidence_source: str = "raw_property_alias",\n    confidence: str = "high",\n) -> tuple[str, str | None, str, str, list[dict[str, Any]], list[str]]:\n    if not matches:\n        return "未知", None, "未知", "unknown", [], ["unknown_property_type"]\n    # A generic alias embedded in a longer explicit type (e.g. "别墅" inside\n    # "联排别墅") must not manufacture a contradiction. Retain independent\n    # current-listing type mentions such as "排屋/别墅" as an ambiguity.\n    specific_hits = [item for item in matches if len(item[1]) > 2]\n    filtered: list[tuple[PropertyRule, str, int]] = []\n    for candidate in matches:\n        rule, alias, _position = candidate\n        if len(alias) <= 2 and any(\n            alias in other_alias and rule.family != other_rule.family\n            for other_rule, other_alias, _ in specific_hits\n        ):\n            continue\n        filtered.append(candidate)\n    matches = filtered\n    families = {rule.family for rule, _alias, _position in matches}\n    evidence = [\n        _evidence(rule.display, evidence_source, confidence, alias)\n        for rule, alias, _position in matches\n    ]\n    if len(families) > 1:\n        return "未知", None, "未知", "ambiguous", evidence, ["ambiguous_property_type"]\n    matches.sort(key=lambda item: (-len(item[1]), item[2]))\n    rule = matches[0][0]\n    return rule.family, rule.subtype or None, rule.display, "confirmed", evidence, []\n\n\ndef _extract_property(text: str) -> tuple[str, str | None, str, str, list[dict[str, Any]], list[str]]:\n    current_text, inventory_segments = _strip_inventory_menu_segments(text)\n\n    # Explicit current-listing type fields are authoritative over descriptive\n    # mentions elsewhere in the post. Inventory/menu lines are excluded first.\n    explicit_scopes = [\n        line for line in current_text.splitlines()\n        if re.search(r"(?:房源类型|物业类型|房屋类型|房产类型)\\s*[:：]", line, flags=re.I)\n    ]\n    explicit_matches = _property_matches("\\n".join(explicit_scopes))\n    if explicit_matches:\n        return _resolve_property_matches(\n            explicit_matches, evidence_source="raw_explicit_property_type", confidence="high"\n        )\n\n    current_matches = _property_matches(current_text)\n    if current_matches:\n        return _resolve_property_matches(current_matches)\n\n    # A type seen only in a stock/menu list is not the current listing's type.\n    # Preserve evidence for review, but never turn it into a confirmed fact.\n    inventory_matches = _property_matches("\\n".join(inventory_segments))\n    if inventory_matches:\n        evidence = [\n            _evidence(rule.display, "raw_inventory_property_alias", "medium", alias)\n            for rule, alias, _position in inventory_matches\n        ]\n        return "未知", None, "未知", "unknown", evidence, [\n            "unknown_property_type", "property_type_only_in_inventory"\n        ]\n    return "未知", None, "未知", "unknown", [], ["unknown_property_type"]\n'''
replace_once(taxonomy, old_property, new_property)

regression.write_text(
    '''from __future__ import annotations\n\nimport pytest\n\nfrom qiaolian_dual.canonical_fact_projection import package_gate\nfrom qiaolian_dual.canonical_facts import PARSER_REVISION, canonicalize_source\n\n\n@pytest.mark.parametrize(\n    ("line", "expected"),\n    [\n        ("出租价格：$1,500/月", 1500),\n        ("出租价格：$850/月", 850),\n        ("租金520$包物业", 520),\n        ("特价出租600$", 600),\n        ("出租情况：850$", 850),\n        ("💰租金：7000美元每月", 7000),\n    ],\n)\ndef test_verified_rent_formats_from_review_corpus(line: str, expected: int) -> None:\n    facts = canonicalize_source(f"区域：BKK1\\n公寓出租\\n1房1卫\\n{line}")\n    assert facts["parser_revision"] == PARSER_REVISION == "v1.2"\n    assert facts["monthly_rent_usd"] == expected\n    assert facts["price_status"] == "confirmed"\n    assert "missing_price" not in facts["quality"]["hard_flags"]\n\n\ndef test_sale_only_keeps_sale_price_without_fake_missing_rent() -> None:\n    facts = canonicalize_source(\n        "区域：BKK1\\n商铺出售\\n售价：$90,000\\n面积：120㎡"\n    )\n    assert facts["deal_type"] == "sale"\n    assert facts["sale_price_usd"] == 90000\n    assert facts["monthly_rent_usd"] is None\n    assert "missing_price" not in facts["quality"]["hard_flags"]\n    assert "non_rental_source" in facts["quality"]["hard_flags"]\n    assert package_gate(facts, 4)["ok"] is False\n\n\ndef test_mixed_listing_keeps_rent_and_sale_as_separate_facts() -> None:\n    facts = canonicalize_source(\n        "区域：BKK1\\n公寓可出租，也可出售\\n2房2卫\\n租金：$680/月\\n售价：$100,000"\n    )\n    assert facts["deal_type"] == "mixed"\n    assert facts["monthly_rent_usd"] == 680\n    assert facts["sale_price_usd"] == 100000\n    assert "mixed_sale_rent_terms" in facts["quality"]["review_flags"]\n    assert package_gate(facts, 4)["ok"] is False\n\n\ndef test_deposit_utility_and_sale_amounts_never_become_rent() -> None:\n    facts = canonicalize_source(\n        "区域：BKK1\\n公寓出租，也可出售\\n1房1卫\\n押金：$1000\\n电费：$0.25/度\\n售价：$100000"\n    )\n    assert facts["monthly_rent_usd"] is None\n    assert facts["sale_price_usd"] == 100000\n    assert "missing_price" in facts["quality"]["hard_flags"]\n\n\ndef test_compound_one_road_and_peng_huoth_city_are_split() -> None:\n    facts = canonicalize_source(\n        "一号公路炳发城 别墅出租\\n4房5卫\\n租金：$2300/月"\n    )\n    assert "一号路" in facts["market_location_keys"]\n    assert "炳发城" in facts["market_location_keys"]\n    assert facts["project_name"] == "炳发城"\n    assert facts["project_brand"] == "Peng Huoth"\n    assert facts["public_location_key"] == "一号路"\n\n\ndef test_yongwang2_and_598_road_are_independent_tokens() -> None:\n    facts = canonicalize_source(\n        "永旺2附近598路 公寓出租\\n1房1卫\\n租金：$650/月"\n    )\n    assert "598路" in facts["market_location_keys"]\n    assert "永旺2" in facts["market_location_keys"]\n    assert facts["public_location_key"] == "598路"\n\n\ndef test_50m_road_is_a_conservative_market_location() -> None:\n    facts = canonicalize_source("50米路 公寓出租\\n1房1卫\\n租金：$500/月")\n    assert facts["public_location_key"] == "50米路"\n    assert facts["public_location_display"] == "50米路附近"\n    assert facts["canonical_area_key"] is None\n\n\ndef test_inventory_room_menu_cannot_manufacture_current_property_type() -> None:\n    facts = canonicalize_source(\n        "【两房两卫出租】\\n区域：BKK1\\n房间户型：2房2卫\\n"\n        "户型选择：单间公寓／1房公寓／2房公寓均有\\n出租价格：$850/月"\n    )\n    assert facts["layout"] == "2房2卫"\n    assert facts["property_type"] == "未知"\n    assert "property_type_only_in_inventory" in facts["candidate_flags"]\n\n\ndef test_explicit_current_property_type_beats_inventory_menu() -> None:\n    facts = canonicalize_source(\n        "公寓两房出租\\n区域：BKK1\\n房间户型：2房2卫\\n"\n        "户型选择：单间公寓／别墅／排屋均有\\n出租价格：$850/月"\n    )\n    assert facts["property_type"] == "公寓"\n    assert facts["property_type_status"] == "confirmed"\n    assert "ambiguous_property_type" not in facts["candidate_flags"]\n\n\ndef test_unapproved_compound_project_token_is_not_invented() -> None:\n    facts = canonicalize_source("BKK1白金湾 公寓出租\\n1房1卫\\n租金：$520/月")\n    assert facts["public_location_key"] == "BKK1"\n    assert facts["project_name"] is None\n    assert facts["project_key"] is None\n''',
    encoding="utf-8",
)

# Keep the targeted parser regression suite in the ordinary branch CI after the
# one-time patch workflow deletes itself.
ci_text = ci.read_text(encoding="utf-8")
needle = "          tests/test_parser_v2_safe.py \\\\\n          tests/test_media_pipeline_v11.py\n"
replacement = "          tests/test_parser_v2_safe.py \\\\\n          tests/test_parser_v12_regressions.py \\\\\n          tests/test_ai_parser_price_gate.py \\\\\n          tests/test_area_gate_single_source.py \\\\\n          tests/test_media_pipeline_v11.py\n"
if needle not in ci_text:
    raise RuntimeError("qiaolian-ui-check parser insertion point changed")
ci.write_text(ci_text.replace(needle, replacement, 1), encoding="utf-8")

print("parser v1.2 patch applied")
